css:
.quests .q-example{font-family:var(--mono);font-size:13px;color:var(--gold);border:1px dashed var(--gold);border-radius:4px;padding:8px 12px;display:inline-block;margin:0 0 14px}
.q-table{display:grid;border:1px solid var(--line);border-radius:6px;overflow:hidden;background:var(--bg2)}
.q-row{display:grid;grid-template-columns:minmax(0,3fr) minmax(0,1fr) minmax(0,1fr) minmax(0,.9fr) auto;gap:16px;align-items:center;padding:14px 18px;border-top:1px solid var(--line);font-size:15.5px;color:var(--ink2)}
.q-row:first-child{border-top:0}
.q-row b{color:var(--ink);font-weight:600}
.q-head{font-family:var(--mono);font-size:11.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--mute);background:var(--panel)}
.q-bounty{font-family:var(--mono);color:var(--cyan)}
.q-tag{font-family:var(--mono);font-style:normal;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--gold);border:1px solid var(--gold);border-radius:3px;padding:2px 6px;white-space:nowrap}
.q-note{margin:14px 0 0;font-size:15px;color:var(--ink);border-left:3px solid var(--gold);padding:6px 12px}
.q-lb-head{margin:56px 0 18px}
.q-lb-head h3{font-family:var(--serif);font-weight:300;font-size:clamp(24px,3vw,32px)}
.q-lb .q-row{grid-template-columns:70px minmax(0,2fr) minmax(0,1fr) minmax(0,1fr)}
@media (max-width:760px){.q-row,.q-lb .q-row{grid-template-columns:1fr 1fr;row-gap:6px}.q-head{display:none}.q-row>span:first-child{grid-column:1/-1}}
